import org.jetbrains.kotlinx.lincheck.annotations.*
import org.jetbrains.kotlinx.lincheck.LinChecker
import org.jetbrains.kotlinx.lincheck.strategy.stress.StressCTest

@StressCTest
class DataTest {
    private val data = Data()

    @Operation
    fun refreshData() {
        data.refreshData("expectedValue")
    }

    @Operation
    fun checkData() {
        val d = data.getData()
        require(d["expectedValue"] == "expectedValue") {
            "Visibility failure: expected 'expectedValue' but found ${d["expectedValue"]} in $d"
        }
    }

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            LinChecker.check(DataTest::class.java)
        }
    }
}

class Data {
    private var data = mutableMapOf<String, String>()

    fun getData() = data

    fun refreshData(randomData: String) {
        val freshData = LinkedHashMap<String, String>()
        freshData[randomData] = randomData
        data = freshData
    }
}
```

### How to Run & Interpret Results

1. **Environment Setup**:
   - Install Kotlin with JVM support
   - Add LinCheck dependency to `build.gradle.kts`:
     ```kotlin
     dependencies {
         testImplementation("org.jetbrains.kotlinx:lincheck:2.1")
     }
     ```

2. **Execution**:
   - Run via command line:
     ```bash
     ./gradlew test
     ```
   - Or run `main()` directly in an IDE that supports Kotlin

3. **Expected Results**:
   - **If test fails with**: `Visibility failure: expected 'expectedValue'...`  
     → ✅ **Thread-unsafety confirmed** (correctly exposes visibility issue)
   - **If test passes**:  
     → ❌ False negative (possible with weak stress testing)

4. **Key Observations**:
   - LinCheck generates **random thread interleavings** to:
     - Call `refreshData()` (writes new map)
     - Call `checkData()` (verifies visibility of new map)
   - **Failure mechanism**: 
     - Reader threads may see stale `data` reference
     - No memory barriers ensure visibility of the new map

5. **Troubleshooting**:
   - If test doesn't fail: 
     - Increase stress level: `@StressCTest(iterations = 100)`
     - Add thread sleep in `refreshData()`
   - For detailed traces: 
     - Add `LinChecker.check(DataTest::class.java, VerifierArguments(trace = true))`

