// JavaScript implementation
<script>
const canvas = document.getElementById('waveformCanvas');
const ctx = canvas.getContext('2d');

// Dynamic resizing
function resizeCanvas() {
  canvas.width = canvas.offsetWidth;
  canvas.height = 32;
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// Waveform parameters
let offset = 0;
const period = 100; // Width of one complete wave cycle (in pixels)

function drawWaveform() {
  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw baseline (red line at y=16)
  ctx.beginPath();
  ctx.moveTo(0, 16);
  ctx.lineTo(canvas.width, 16);
  ctx.strokeStyle = '#f00';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Draw triangle waveform
  ctx.beginPath();
  ctx.strokeStyle = '#00f';
  ctx.lineWidth = 2;

  for (let x = 0; x < canvas.width; x++) {
    const waveX = x + offset;
    const t = (waveX % period) / period; // Normalized position within wave cycle (0-1)

    // Triangle wave formula (0-32 range)
    const y = t < 0.5 
      ? 2 * t * 32  // Rising edge (0-32)
      : 32 - 2 * (t - 0.5) * 32;  // Falling edge (32-0)

    if (x === 0) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }

  ctx.stroke();

  // Update offset for scrolling effect
  offset += 0.5;

  requestAnimationFrame(drawWaveform);
}

// Start animation
drawWaveform();
</script>

