    fetchPoints();
  }, []);

  // Calculate scaled coordinates for a point
  const getScaledPoint = (point) => {
    const scaledX = (point.x / 2160) * (screenDim.width - 2 * padding) + padding;
    const scaledY = (point.y / 2160) * (screenDim.height - 2 * padding) + padding;
    return { x: scaledX, y: scaledY };
  };

  // Find closest point to touch coordinates
  const findClosestPoint = (x, y) => {
    const startIdx = currentBatch * batchSize;
    const endIdx = Math.min(startIdx + batchSize, points.length);
    let minDist = 2500; // 50px radius threshold (50^2 = 2500)
    let closest = null;

    for (let i = startIdx; i < endIdx; i++) {
      const scaled = getScaledPoint(points[i]);
      const dx = scaled.x - x;
      const dy = scaled.y - y;
      const dist = dx * dx + dy * dy;

      if (dist < minDist) {
        minDist = dist;
        closest = scaled;
      }
    }

    return minDist < 2500 ? closest : null;
  };

  // PanResponder for touch handling
