function [publicKey, privateKey] = generateRSAKeys()
    % Generate two distinct large prime numbers p and q
    % Using MATLAB's primes() function to get a list of primes up to a limit
    primes = primes(1000); % Select primes up to 1000 for demonstration
    p = datasample(primes, 1); % Randomly select p
    q = datasample(setdiff(primes, p), 1); % Randomly select q ≠ p

    % Compute modulus n = p * q
    n = p * q;

    % Compute Euler's totient phi(n) = (p-1)*(q-1)
    phi = (p - 1) * (q - 1);

    % Choose public exponent e such that 1 < e < phi(n) and gcd(e, phi(n)) = 1
    e = 65537; % Commonly used value for e
    while gcd(e, phi) ~= 1
        e = randi([2 phi-1]);
    end

    % Compute private exponent d = e^(-1) mod phi(n)
    d = modinv(e, phi);

    % Public key: (e, n), Private key: (d, n)
    publicKey = [e n];
    privateKey = [d n];
end

