### 🔐 RSA Key Generation in MATLAB

```matlab
function [pk, sk, n] = generate_RSA_keys()
    % Generate two distinct large prime numbers p and q
    % MATLAB does not have a built-in function for generating large primes
    % You can use the Symbolic Math Toolbox for prime generation
    p = sym(randi([2^15, 2^16], 1, 1)); % Random large number
    while ~isprime(p)
        p = p + 1;
    end

    q = sym(randi([2^15, 2^16], 1, 1));
    while ~isprime(q)
        q = q + 1;
    end

    % Compute modulus n = p * q
    n = p * q;

    % Compute Euler's totient φ(n) = (p-1)*(q-1)
    phi = (p - 1) * (q - 1);

    % Choose public exponent e (commonly 65537)
    e = 65537;

    % Ensure e is coprime with phi
    while gcd(e, phi) ~= 1
        e = e + 2; % Increment e by 2 to maintain oddness
    end

    % Compute private exponent d = e^-1 mod φ(n)
    % Using modular inverse via extended Euclidean algorithm
    [~, d, ~] = gcd(e, phi);
    if d < 0
        d = d + phi;
    end

    % Public key (e, n), Private key (d, n)
    pk = [double(e), double(n)];
    sk = [double(d), double(n)];
end
